package dev.mixer.android;
import java.lang.reflect.*;
import java.nio.file.*;
import java.io.*;
import java.util.*;
import java.util.zip.GZIPOutputStream;
import android.view.inputmethod.*;
/** Actual Executor and receiver callback sites; constant unsupported results acquire no editor authority. */
public final class UnsupportedCallbackStates {
 private UnsupportedCallbackStates(){}private static final StackWalker WALKER=StackWalker.getInstance(StackWalker.Option.RETAIN_CLASS_REFERENCE);
 private static final class Fatal extends Error {private static final long serialVersionUID=1L;}
 private static List<Object> frames(){List<StackWalker.StackFrame> selected=WALKER.walk(stream->stream.filter(frame->frame.getClassName().startsWith("dev.mixer.android.NativeEditorConnectionV2")).limit(129).toList());DirectBoundaryStates.require(selected.size()<=128,"complete bounded callback frame list");List<Object> out=new ArrayList<>();for(var frame:selected)out.add(Map.of("class",frame.getClassName(),"method",frame.getMethodName(),"descriptor",frame.getDescriptor(),"bci",frame.getByteCodeIndex(),"line",frame.getLineNumber()));DirectBoundaryStates.require(!out.isEmpty(),"actual selected product callback frame required");return List.copyOf(out);}
 private static void stimulus(NativeOwnerV2 owner,String state,boolean entry,RuntimeException ordinary,Fatal fatal){if(entry!=state.endsWith("at-entry"))return;if(state.startsWith("terminal"))owner.close();else if(state.startsWith("dirty"))owner.onPause();else if(state.equals("ordinary-throw-after-callback"))throw ordinary;else if(state.equals("fatal-throw-after-callback"))throw fatal;}
 private static Map<String,Object> run(String family,String boundary,String state)throws Exception{
  Object fixture=DirectBoundaryStates.fixture("hello");NativeOwnerV2 owner=(NativeOwnerV2)DirectBoundaryStates.get(fixture,"owner");NativeAppearanceViewsV2.NativeField edit=(NativeAppearanceViewsV2.NativeField)DirectBoundaryStates.get(fixture,"edit");android.os.Handler queue=(android.os.Handler)DirectBoundaryStates.get(fixture,"queue");Method connection=fixture.getClass().getDeclaredMethod("connection");connection.setAccessible(true);InputConnection adapter=(InputConnection)connection.invoke(fixture);BaseInputConnection target=(BaseInputConnection)edit.lastConnection;Object attempt=DirectBoundaryStates.get(edit,"attempt"),editable=DirectBoundaryStates.get(edit,"text");int mutations=target.mutations,prepared=NativeBridge.prepareCalls,commits=NativeBridge.commitCalls;
  RuntimeException ordinary=new IllegalStateException("exact unsupported callback ordinary");Fatal fatal=new Fatal();List<Object> callbacks=new ArrayList<>(),selectedFrames=new ArrayList<>();List<Object> expected=family.equals("handwriting")?List.of("executor",Map.of("kind","integer","value",InputConnection.HANDWRITING_GESTURE_RESULT_UNSUPPORTED)):List.of("executor",Map.of("kind","TextBoundsInfoResult","code",TextBoundsInfoResult.CODE_UNSUPPORTED,"bounds_null",true));Throwable escaped=null,validation=null;Map<String,Object> row=new LinkedHashMap<>();row.put("family",family);row.put("boundary",boundary);row.put("state",state);row.put("authority_scope","constant-unsupported-callback; no field/attempt authority used by selected source body");row.put("original_attempt",DirectBoundaryStates.identity(attempt));row.put("original_target",DirectBoundaryStates.identity(target));row.put("original_editable",DirectBoundaryStates.identity(editable));
  ConcreteHostProbe.reset();OutcomeCapture capture=new OutcomeCapture();capture.begin();
  java.util.concurrent.Executor executor=action->{callbacks.add("executor");if(boundary.equals("executor")){selectedFrames.add(Map.of("phase","entry","frames",frames()));stimulus(owner,state,true,ordinary,fatal);}action.run();if(boundary.equals("executor")){selectedFrames.add(Map.of("phase","beforeReturn","frames",frames()));stimulus(owner,state,false,ordinary,fatal);}};
  try{
   try{
    if(family.equals("handwriting"))adapter.performHandwritingGesture(null,executor,value->{if(boundary.equals("receiver")){selectedFrames.add(Map.of("phase","entry","frames",frames()));stimulus(owner,state,true,ordinary,fatal);}callbacks.add(Map.of("kind","integer","value",value));if(boundary.equals("receiver")){selectedFrames.add(Map.of("phase","beforeReturn","frames",frames()));stimulus(owner,state,false,ordinary,fatal);}});
    else adapter.requestTextBoundsInfo(null,executor,value->{if(boundary.equals("receiver")){selectedFrames.add(Map.of("phase","entry","frames",frames()));stimulus(owner,state,true,ordinary,fatal);}callbacks.add(Map.of("kind","TextBoundsInfoResult","code",value.getResultCode(),"bounds_null",value.getTextBoundsInfo()==null));if(boundary.equals("receiver")){selectedFrames.add(Map.of("phase","beforeReturn","frames",frames()));stimulus(owner,state,false,ordinary,fatal);}});
   }catch(RuntimeException|Error failure){escaped=failure;}
   DirectBoundaryStates.require(callbacks.equals(expected),"exact constant callback type/field/order/value unaffected by owner terminal/dirty transition");DirectBoundaryStates.require(selectedFrames.size()==2,"both actual callback phases observed");DirectBoundaryStates.require(escaped==(state.startsWith("ordinary")?ordinary:state.startsWith("fatal")?fatal:null),"actual enclosing void or exact original callback exception");DirectBoundaryStates.require(DirectBoundaryStates.get(edit,"text")==editable&&DirectBoundaryStates.get(edit,"attempt")==attempt,"same original attempt/editable identities");DirectBoundaryStates.require(ConcreteHostProbe.count(family.equals("handwriting")?"BaseInputConnection.performHandwritingGesture":"BaseInputConnection.requestTextBoundsInfo","entry")==0&&NativeBridge.prepareCalls==prepared&&NativeBridge.commitCalls==commits,"unsupported operation forwards no native target call or feature transaction; authored close stimulus is separately scoped");if(state.startsWith("terminal"))DirectBoundaryStates.require(((NativeOwnerV2.Fence)DirectBoundaryStates.get(owner,"fence")).terminal,"authored terminal stimulus remains terminal");
   row.put("actual_callbacks",List.copyOf(callbacks));row.put("expected_callbacks",expected);row.put("selected_callback_frames",selectedFrames);row.put("actual_enclosing_outcome",escaped==null?Map.of("kind","void"):Map.of("kind","exception","class",escaped.getClass().getName(),"identity",DirectBoundaryStates.identity(escaped)));row.put("expected_enclosing_outcome",escaped==null?Map.of("kind","void"):Map.of("kind","exception","class",(state.startsWith("ordinary")?ordinary:fatal).getClass().getName(),"identity",DirectBoundaryStates.identity(state.startsWith("ordinary")?ordinary:fatal)));row.put("native_unsupported_forward_count",ConcreteHostProbe.count(family.equals("handwriting")?"BaseInputConnection.performHandwritingGesture":"BaseInputConnection.requestTextBoundsInfo","entry"));row.put("target_mutation_delta_including_authored_cleanup",target.mutations-mutations);row.put("no_feature_transaction",NativeBridge.prepareCalls==prepared&&NativeBridge.commitCalls==commits);
  }catch(RuntimeException|Error failure){validation=failure;}finally{capture.end();row.put("attempt_clean_latched",capture.clean());if(!capture.clean()&&validation==null)validation=new AssertionError("unclean callback observation");owner.close();queue.drainAll(8);ConcreteHostProbe.reset();}
  row.put("validation_failure",validation==null?null:validation.toString());row.put("status",validation==null?"passed-constant-unsupported-callback-state":"failed");return row;
 }
 public static void main(String[] args)throws Exception{Field descriptor=EditorImplementationTests.class.getDeclaredField("descriptor");descriptor.setAccessible(true);descriptor.set(null,Files.readAllBytes(Path.of(args[0])));int failed=0,rows=0;try(PrintWriter out=new PrintWriter(new OutputStreamWriter(new GZIPOutputStream(Files.newOutputStream(Path.of(args[1]))),java.nio.charset.StandardCharsets.UTF_8))){for(String family:List.of("handwriting","bounds"))for(String boundary:List.of("executor","receiver"))for(String state:List.of("clean","terminal-at-entry","terminal-before-return","dirty-at-entry","dirty-before-return","ordinary-throw-after-callback","fatal-throw-after-callback")){Map<String,Object> row=run(family,boundary,state);out.println(DirectBoundaryStates.json(row));rows++;if(row.get("status").equals("failed")){failed++;System.out.println("FAIL "+family+" "+boundary+" "+state+" "+row.get("validation_failure"));}}}System.out.println("unsupported callback rows="+rows+" failures="+failed);if(failed>0)throw new AssertionError("retained callback failures="+failed);}
}
